using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class PurchaseInvoiceRepository(NamaaDbContext db):IPurchaseInvoiceRepository{public Task<bool>ExistsByNumberAsync(string number,CancellationToken cancellationToken=default)=>db.PurchaseInvoices.AsNoTracking().AnyAsync(e=>e.PurchaseInvoiceNumber==number,cancellationToken);public Task<PurchaseInvoice?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.PurchaseInvoices.AsNoTracking().Include(e=>e.Items).SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<PurchaseInvoice?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.PurchaseInvoices.Include(e=>e.Items).SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<PurchaseInvoice>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.PurchaseInvoices.AsNoTracking().Include(e=>e.Items).OrderByDescending(e=>e.IssueDate).ToListAsync(cancellationToken);public async Task AddAsync(PurchaseInvoice entity,CancellationToken cancellationToken=default)=>await db.PurchaseInvoices.AddAsync(entity,cancellationToken);}
